$('#formula').onclick=()=>modal('Volume, with the working shown',`<p class="modal-copy">Volume = region voxel count × physical voxel volume ÷ 1,000.<br>Physical voxel volume = |det(affine₃×₃)|. This also handles rotated and sheared grids.</p><div class="info-card"><table><tr><th>Region</th><th>Voxels</th><th>Voxel volume</th><th>Estimated volume</th></tr>${['WT','TC','ET'].map(k=>`<tr><td>${k}</td><td>${state.meta.regions[k].voxel_count}</td><td>${(state.meta.regions[k].voxel_volume_mm3??Math.abs(det3(state.meta.affine))).toFixed(4)} mm³</td><td>${state.meta.regions[k].volume_ml.toFixed(3)} mL</td></tr>`).join('')}</table></div><p class="modal-copy">${state.meta.demo?'These teaching regions are synthetic. No model accuracy or uncertainty is implied.':'These are suspected tumour regions predicted by the model, not a diagnosis.'}</p>`);
