 renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0,0);el.prepend(renderer.domElement);
 root=new THREE.Group();scene.add(root);marker=new THREE.Mesh(new THREE.SphereGeometry(1,16,16),new THREE.MeshBasicMaterial({color:0xf0f7ff,depthTest:false}));marker.renderOrder=20;root.add(marker);planeGroup=new THREE.Group();root.add(planeGroup);theatre=new THREE.Group();root.add(theatre);
 const resize=()=>{const w=el.clientWidth,h=el.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()};new ResizeObserver(resize).observe(el);
