 renderer.domElement.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(drag.shift){pan[0]-=dx*.25;pan[1]+=dy*.25}else{phi-=dx*.008;theta=Math.max(-1.35,Math.min(1.35,theta+dy*.008));state.auto=false;$('#rotate').classList.remove('selected')}drag.x=e.clientX;drag.y=e.clientY};renderer.domElement.onpointerup=()=>drag=null;renderer.domElement.onpointercancel=()=>drag=null;
 renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();distance=Math.max(100,Math.min(850,distance+e.deltaY*.18))},{passive:false});
