  for(let i=0;i<v.length;i+=3){const y=v[i+1];v[i+1]=v[i+2];v[i+2]=-y-20}g.setAttribute('position',new THREE.BufferAttribute(v,3));g.setIndex(value.indices);g.computeVertexNormals();g.computeBoundingBox();
