function animateStudio(dt){
 if(!state.meshes.brain)return;const separate=studioMode==='separate';const right=new THREE.Vector3(Math.cos(phi),0,-Math.sin(phi));const centre=state.meshes.TC?.userData.centre||state.meshes.brain.userData.centre;
 for(const [key,m] of Object.entries(state.meshes)){
  let target=new THREE.Vector3();if(separate&&key!=='brain')target.copy(centre).sub(m.userData.centre).addScaledVector(right,({WT:-75,TC:0,ET:75})[key]);
  m.position.lerp(target,matchMedia('(prefers-reduced-motion: reduce)').matches?1:Math.min(1,dt*7));
  let opacity=state.layers[key].opacity;if(key==='brain'&&(separate||studioMode==='theatre'))opacity*=.3;if(studioFocus&&key!=='brain'&&key!==studioFocus)opacity*=.12;
  m.material.uniforms.alpha.value=opacity;m.visible=state.layers[key].visible;
  if(key==='brain'&&brainBounds)m.material.uniforms.cut.value=brainBounds.max.x-(brainBounds.max.x-brainBounds.min.x)*peel/100;
 }
 theatre.visible=studioMode==='theatre';marker.visible=!separate;planeGroup.visible=!separate;
}
