 for(const key of ['WT','TC','ET']){const el=$(`#callout-${key}`),m=state.meshes[key];if(!el||!m)continue;el.hidden=studioMode!=='separate'||!state.layers[key].visible;if(el.hidden)continue;
  const p=m.userData.centre.clone();m.localToWorld(p);p.project(camera);el.style.left=`${(p.x*.5+.5)*rect.width}px`;el.style.top=`${(-p.y*.5+.5)*rect.height+35}px`;
 }
