function drawPlane(target,c,data,overlay=true){
 const sh=state.meta.shape,w=sh[c.u],h=sh[c.v];target.width=w;target.height=h;const ctx=target.getContext('2d'),img=ctx.createImageData(w,h);
 const level=Number($('#window-level')?.value??50),contrast=Number($('#window-width')?.value??100)/100;
 for(let y=0;y<h;y++)for(let x=0;x<w;x++){
  const p=[...state.position];p[c.u]=x;p[c.v]=h-1-y;const idx=p[0]+sh[0]*(p[1]+sh[1]*p[2]),d=4*(x+w*y);const g=Math.max(0,Math.min(255,((data[idx]||0)-127.5)*contrast+127.5+(50-level)*2));
  img.data[d]=img.data[d+1]=img.data[d+2]=g;img.data[d+3]=255;const label=state.labels?.[idx]||0;
  const key=label===4&&state.layers.ET.visible?'ET':(label===1||label===4)&&state.layers.TC.visible?'TC':label>0&&state.layers.WT.visible?'WT':null;
  if(overlay&&key){const l=state.layers[key],blend=l.opacity*.68;for(let j=0;j<3;j++)img.data[d+j]=g*(1-blend)+parseInt(l.color.slice(1+j*2,3+j*2),16)*blend;}
 }
 ctx.putImageData(img,0,0);return ctx;
}
function drawCrosshair(ctx,c,width,height){
 const px=state.position[c.u]+.5,py=height-1-state.position[c.v]+.5;ctx.strokeStyle='#96d5f0c0';ctx.lineWidth=.65;ctx.beginPath();ctx.moveTo(px,0);ctx.lineTo(px,py-4);ctx.moveTo(px,py+4);ctx.lineTo(px,height);ctx.moveTo(0,py);ctx.lineTo(px-4,py);ctx.moveTo(px+4,py);ctx.lineTo(width,py);ctx.stroke();
}
function drawSlices(){
 if(!state.data||!state.meta)return;const shape=state.meta.shape;
 configs.forEach((c,i)=>{const can=$(`#slice-${i}`);if(!can)return;const ctx=drawPlane(can,c,state.data);drawCrosshair(ctx,c,can.width,can.height);$(`#slider-${i}`).value=state.position[c.axis];$(`#slice-label-${i}`).textContent=`${['X','Y','Z'][c.axis]} = ${state.position[c.axis]} / ${shape[c.axis]-1}`});
 drawContrastDeck();if(studioMode==='theatre')updateTheatre();
}
function updateTheatre(){
 if(!theatre||!state.data||!state.meta)return;
 while(theatre.children.length){const m=theatre.children[0];theatre.remove(m);m.geometry.dispose();m.material.map?.dispose();m.material.dispose()}
 const sh=state.meta.shape;
 for(const c of configs){
  const canvas=document.createElement('canvas');drawPlane(canvas,c,state.data,false);const texture=new THREE.CanvasTexture(canvas);texture.minFilter=THREE.LinearFilter;
  const corners=[[0,sh[c.v]-1],[sh[c.u]-1,sh[c.v]-1],[0,0],[sh[c.u]-1,0]],coords=[];
  for(const [u,v] of corners){const p=[...state.position];p[c.u]=u;p[c.v]=v;const w=affine(p);coords.push(w[0],w[2],-w[1]-20)}
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(coords,3));g.setAttribute('uv',new THREE.Float32BufferAttribute([0,1,1,1,0,0,1,0],2));g.setIndex([0,2,1,1,2,3]);g.computeVertexNormals();
  const m=new THREE.Mesh(g,new THREE.MeshBasicMaterial({map:texture,side:THREE.DoubleSide,transparent:true,opacity:.84,depthWrite:true}));m.renderOrder=1;theatre.add(m);
 }
}
async function switchSequence(seq){
 const request=++sequenceRequest;const job=state.job;
 try{
  if(!volumeCache[seq]){const url=job?`/api/jobs/${job}/volume/${seq}`:`assets/${seq}.bin`;const r=await fetch(url);if(!r.ok)throw Error('Sequence unavailable');const array=new Uint8Array(await r.arrayBuffer());if(array.length!==state.meta.shape.reduce((a,b)=>a*b,1))throw Error('Invalid sequence payload');if(job!==state.job)return;volumeCache[seq]=array;}
  if(request!==sequenceRequest)return;state.data=volumeCache[seq];state.sequence=seq;$$('[data-seq]').forEach(b=>{b.classList.toggle('active',b.dataset.seq===seq);b.setAttribute('aria-pressed',String(b.dataset.seq===seq))});
  $('#active-sequence').textContent=seq;$('#sequence-explainer').textContent=sequenceCopy[seq];drawSlices();
 }catch{toast(`${seq} could not be loaded. The previous sequence remains visible.`)}
}
function drawContrastDeck(){
 if(!state.meta||!$('#contrast-deck'))return;const c=configs[0];
 for(const seq of ['T1','T1Gd','T2','FLAIR']){const can=$(`#contrast-${seq}`);if(!can)continue;const data=volumeCache[seq];if(data){const ctx=drawPlane(can,c,data,$('#deck-overlay')?.checked);drawCrosshair(ctx,c,can.width,can.height)}can.closest('.contrast-card').classList.toggle('active',seq===state.sequence)}
 $('#deck-position').textContent=`AXIAL Z ${state.position[2]} · SHARED CROSSHAIR`;
}
