 $$('[data-studio]').forEach(b=>b.onclick=()=>setStudioMode(b.dataset.studio));
 $('#peel').oninput=e=>{peel=Number(e.target.value);$('#peel-value').textContent=peel+'%';};
 $$('[data-focus]').forEach(b=>b.onclick=()=>{studioFocus=studioFocus===b.dataset.focus?null:b.dataset.focus;$$('[data-focus]').forEach(x=>{x.classList.toggle('active',x.dataset.focus===studioFocus);x.setAttribute('aria-pressed',String(x.dataset.focus===studioFocus))});});
 $$('[data-camera]').forEach(b=>b.onclick=()=>{state.auto=false;$('#rotate').classList.remove('selected');pan=[0,0];const v={lateral:[Math.PI/2,0],anterior:[0,0],superior:[0,1.54],perspective:[1.05,.35]}[b.dataset.camera];[phi,theta]=v;});
 $('#window-level').oninput=$('#window-width').oninput=()=>drawSlices();$('#deck-overlay').onchange=drawContrastDeck;
 $$('[data-select-seq]').forEach(b=>b.onclick=()=>switchSequence(b.dataset.selectSeq));
