 $('#studio-reset').onclick=()=>{peel=0;$('#peel').value=0;$('#peel-value').textContent='0%';studioFocus=null;$$('[data-focus]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});$('#reset').click();setStudioMode('anatomy')};
 updateStudioLabels();setStudioMode('anatomy');
