 const [meta,lab,mesh,...bins]=await Promise.all([fetch('assets/reference.json').then(r=>r.json()),fetch('assets/labels.bin').then(r=>r.arrayBuffer()),fetch('assets/meshes.json').then(r=>r.json()),...['T1','T1Gd','T2','FLAIR'].map(s=>fetch(`assets/${s}.bin`).then(r=>{if(!r.ok)throw Error(s+' unavailable');return r.arrayBuffer()}))]);
 state.meta=meta;volumeCache={};['T1','T1Gd','T2','FLAIR'].forEach((s,i)=>volumeCache[s]=new Uint8Array(bins[i]));state.data=volumeCache.T1;state.labels=new Uint8Array(lab);state.position=meta.focus_voxel||meta.shape.map(v=>Math.floor(v/2));loadMeshes(mesh);setupSlices();measurements();installStudio();updatePosition();
 $('#study-name').textContent=meta.name;$('#study-sub').textContent='Public research study · acquired sequences · precomputed prediction';$('#mode-badge').textContent='PRECOMPUTED PUBLIC CASE';$('#seq-count').textContent='4 / 4 acquired';
